Rules.InvariantScript:
Patch(
    tbl_inspZPAfotos,
    Defaults(tbl_inspZPAfotos),
    {
        ID_FK: Self.LastSubmit.ID,
        zpa_fotoCabE1: ImageE1.Image,
        zpa_fotoCabE2: ImageE2.Image,
        zpa_fotoCabE3: ImageE3.Image,
        zpa_fotoCabD1: ImageD1.Image,
        zpa_fotoCabD2: ImageD2.Image,
        zpa_fotoCabD3: ImageD3.Image
    }
);
ForAll(
    col_ZPASobstaculos,
    Patch(
        tbl_inspZPAitens,
        Defaults(tbl_inspZPAitens),
        {
            ID_FK: Self.LastSubmit.ID,
            Bloco: Self.LastSubmit.Bloco,
            Aeroporto: Self.LastSubmit.Aeroporto,
            IATA: Self.LastSubmit.IATA,
            Item: ThisRecord.Item,
            Subitem: ThisRecord.Subitem,
            Descricao: ThisRecord.Descricao,
            Localização: ThisRecord.Localização,
            Altura: ThisRecord.Altura,
            Iluminação: ThisRecord.Iluminação,
            Foto: ThisRecord.Foto
        }
    )
);
Navigate(
    frmHomeZPA,
    ScreenTransition.Fade
);
Reset(AddMediaButtonD3);
Reset(AddMediaButtonD2);
Reset(AddMediaButtonD1);
Reset(AddMediaButtonE3);
Reset(AddMediaButtonE2);
Reset(AddMediaButtonE1);
UpdateContext({var_loadSave: false});
Notify(
    "Inspeção finalizada com sucesso!",
    NotificationType.Success
);

